import unittest
import api

class IndependentBehavior(unittest.TestCase):
    def test_padding(self): self.assertIs(api.read_flag("  true  "), True)
    def test_controls(self): self.assertIs(api.read_flag("\tFaLsE\n"), False)
    def test_original(self): self.assertIs(api.read_flag("TRUE"), True)
    def test_unknown(self):
        with self.assertRaises(ValueError): api.read_flag("perhaps")
    def test_empty(self):
        with self.assertRaises(ValueError): api.read_flag("   ")
    def test_other_function(self): self.assertEqual(api.format_flag(True), "true")
